components.css:
.bike-spec__body { display: grid; gap: 1.5rem; }
.bike-spec__media { margin: 0; }
.bike-spec__image { display: block; width: 100%; height: auto; border-radius: 0.5rem; }
.bike-spec__sheet { display: grid; gap: 1.5rem; min-width: 0; }
.bike-spec__key { display: flex; flex-wrap: wrap; gap: 1rem 2.5rem; margin: 0; }
.bike-spec__key-item { margin: 0; }
.bike-spec__key-label { color: var(--cms-color-text-subtle); font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.05em; }
.bike-spec__key-value { margin: 0.25rem 0 0; color: var(--cms-color-text); font-size: 1.75rem; font-weight: 700; line-height: 1.2; }
.bike-spec__specs { margin: 0; border-top: 2px solid var(--cms-color-accent); }
.bike-spec__row { display: grid; gap: 0.25rem; padding: 0.75rem 0; border-bottom: 1px solid var(--cms-color-border); }
.bike-spec__row-label { color: var(--cms-color-text-subtle); font-weight: 600; }
.bike-spec__row-value { margin: 0; color: var(--cms-color-text); overflow-wrap: anywhere; }
.bike-spec__review { display: grid; gap: 1.25rem; padding: 1.25rem; border-radius: 0.5rem; background: var(--cms-color-accent-surface); color: var(--cms-color-text); }
.bike-spec__review p { margin: 0; color: var(--cms-color-text); }
.bike-spec__review .bike-spec__review-label { color: var(--cms-color-text-subtle); font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.05em; }
.bike-spec__score { margin-top: 0.25rem; }
.bike-spec__score-value { font-size: 2rem; font-weight: 700; line-height: 1; }
.bike-spec__meter { display: flex; gap: 0.375rem; margin-top: 0.5rem; }
.bike-spec__dot { width: 1rem; height: 1rem; border-radius: 50%; border: 2px solid var(--cms-color-accent); background: transparent; }
.bike-spec__dot--on { background: var(--cms-color-accent); }
.bike-spec__review .bike-spec__verdict-text { margin-top: 0.25rem; font-size: 1.125rem; font-weight: 600; }
@media (min-width: 48rem) {
.bike-spec__body--media { grid-template-columns: 2fr 3fr; align-items: start; gap: 2.5rem; }
.bike-spec__row { grid-template-columns: 10rem 1fr; gap: 1rem; }
.bike-spec__review { grid-template-columns: auto 1fr; gap: 2rem; align-items: start; }
}

.carousel__title { margin: 0 0 1rem; color: var(--cms-color-text); }
.carousel__viewport { position: relative; overflow-x: auto; scroll-snap-type: x mandatory; overscroll-behavior-x: contain; }
.carousel__viewport:focus-visible { outline: 2px solid var(--cms-color-text); outline-offset: 2px; }
.carousel__track { display: flex; gap: 1rem; margin: 0; padding: 0 0 0.5rem; list-style: none; }
.carousel__slide { flex: 0 0 85%; scroll-snap-align: start; }
.carousel__image { display: block; width: 100%; height: auto; border-radius: 0.5rem; }
.carousel__caption { margin: 0.5rem 0 0; color: var(--cms-color-text-muted); }
@media (min-width: 48rem) { .carousel__slide { flex-basis: 40%; } }

.faq__title { margin: 0 0 1rem; color: var(--cms-color-text); }
.faq__item { padding: 0.75rem 0; border-bottom: 1px solid var(--cms-color-border); }
.faq__question { cursor: pointer; font-weight: 700; color: var(--cms-color-text); }
.faq__answer { padding-top: 0.5rem; color: var(--cms-color-text-muted); }

.imagetext { display: grid; gap: 1.5rem; align-items: center; }
.imagetext__image { display: block; width: 100%; height: auto; border-radius: 0.5rem; }
.imagetext__title { margin: 0 0 0.75rem; color: var(--cms-color-text); }
.imagetext__text { color: var(--cms-color-text); }
.imagetext__link { display: inline-block; margin-top: 1rem; font-weight: 700; color: var(--cms-color-accent); }
@media (min-width: 48rem) { .imagetext { grid-template-columns: 1fr 1fr; gap: 3rem; } .imagetext--right .imagetext__media { order: 2; } }

.figures__title { margin: 0 0 1.5rem; color: var(--cms-color-text); }
.figures__list { display: grid; gap: 1.5rem; margin: 0; padding: 0; list-style: none; }
.figure { display: flex; flex-direction: column; gap: 0.25rem; }
.figure__value { font-size: 2.5rem; font-weight: 700; line-height: 1; color: var(--cms-color-text); }
.figure__label { font-weight: 700; color: var(--cms-color-text); }
.figure__note { color: var(--cms-color-text-muted); }
@media (min-width: 48rem) { .figures__list { grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr)); } }

.quote__figure { margin: 0; padding: 2rem 1.5rem; border-radius: 0.5rem; background: var(--cms-color-surface); }
.quote__text { margin: 0 0 1rem; font-size: 1.375rem; line-height: 1.4; color: var(--cms-color-text); }
.quote__text p { margin: 0; }
.quote__caption { display: flex; flex-wrap: wrap; align-items: center; gap: 0.25rem 0.75rem; }
.quote__portrait { width: 3rem; height: 3rem; border-radius: 50%; object-fit: cover; }
.quote__author { font-weight: 700; color: var(--cms-color-text); }
.quote__role { color: var(--cms-color-text-muted); }
@media (min-width: 48rem) { .quote__figure { padding: 3rem; } .quote__text { font-size: 1.75rem; } }

.rides__list { display: grid; gap: 1.25rem; margin: 0; padding: 0; list-style: none; }
.ride { display: flex; flex-direction: column; gap: 1rem; padding: 1.5rem; background: var(--cms-color-surface); border-top: 4px solid var(--cms-color-accent); border-radius: 0.5rem; }
.ride__title { margin: 0; font-size: 1.25rem; color: var(--cms-color-text); }
.ride__facts { display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem 1rem; margin: 0; }
.ride__fact { min-width: 0; }
.ride__fact--date { grid-column: 1 / -1; }
.ride__fact--start { grid-column: 1 / -1; }
.ride__fact dt { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.05em; color: var(--cms-color-text-subtle); }
.ride__fact dd { margin: 0.15rem 0 0; font-weight: 600; color: var(--cms-color-text); overflow-wrap: anywhere; }
.ride__level { display: flex; align-items: center; gap: 0.5rem; }
.ride__gauge { display: inline-flex; gap: 3px; }
.ride__gauge span { display: block; width: 0.5rem; height: 0.9rem; border-radius: 2px; background: var(--cms-color-border); }
.ride__gauge--easy span:nth-child(1) { background: var(--cms-color-accent); }
.ride__gauge--medium span:nth-child(-n+2) { background: var(--cms-color-accent); }
.ride__gauge--hard span { background: var(--cms-color-accent); }
.ride__button { position: relative; margin-top: auto; align-self: flex-start; display: inline-block; padding: 0.65rem 1.25rem; border-radius: 999px; background: var(--cms-color-accent); color: var(--cms-color-on-accent); font-weight: 600; text-decoration: none; transition: box-shadow 0.2s ease; }
.ride__button:hover { text-decoration: underline; box-shadow: 0 0 0 3px var(--cms-color-accent-strong); }
.ride__button:focus-visible { text-decoration: underline; box-shadow: 0 0 0 3px var(--cms-color-accent-strong); }
.ride__sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
@media (min-width: 48rem) { .rides__list { grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr)); } }

.route { padding: 1.5rem; background: var(--cms-color-surface); border: 1px solid var(--cms-color-border); border-radius: 0.75rem; color: var(--cms-color-text); }
.route__facts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; margin: 1rem 0 0; padding: 0; }
.route__fact { padding-top: 0.75rem; border-top: 2px solid var(--cms-color-accent); }
.route__label { margin: 0; font-size: 0.875rem; color: var(--cms-color-text-subtle); }
.route__value { margin: 0.25rem 0 0; font-size: 1.375rem; font-weight: 700; color: var(--cms-color-text); overflow-wrap: anywhere; }
.route__unit { font-size: 1rem; font-weight: 400; color: var(--cms-color-text-muted); }
.route__difficulty { display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap; }
.route__gauge { display: inline-flex; align-items: flex-end; gap: 0.2rem; }
.route__bar { display: block; width: 0.4rem; border-radius: 2px; background: var(--cms-color-border); }
.route__bar:nth-child(1) { height: 0.6rem; }
.route__bar:nth-child(2) { height: 0.9rem; }
.route__bar:nth-child(3) { height: 1.2rem; }
.route__difficulty--easy .route__bar:nth-child(1) { background: var(--cms-color-accent); }
.route__difficulty--medium .route__bar:nth-child(-n+2) { background: var(--cms-color-accent); }
.route__difficulty--hard .route__bar { background: var(--cms-color-accent); }
.route__gpx { display: inline-block; margin-top: 1.5rem; padding: 0.75rem 1.25rem; border-radius: 0.5rem; background: var(--cms-color-accent); color: var(--cms-color-on-accent); font-weight: 600; text-decoration: underline; transition: background-color 0.2s; }
.route__gpx:hover { background: var(--cms-color-accent-strong); }
.route__gpx:focus-visible { background: var(--cms-color-accent-strong); outline: 2px solid var(--cms-color-accent); outline-offset: 3px; }
@media (min-width: 48rem) { .route { padding: 2rem; } .route__facts { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.5rem; } }

.steps__list { display: grid; gap: 1.5rem; padding: 0; list-style: none; counter-reset: step; }
.step { counter-increment: step; padding-top: 1rem; border-top: 2px solid var(--cms-color-accent); }
.step__title { margin: 0 0 0.5rem; }
.step__title::before { content: counter(step) ". "; }
.step__text { margin: 0; color: var(--cms-color-text-muted); }
@media (min-width: 48rem) { .steps__list { grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr)); } }
